changeSet.sql:
DO $$
BEGIN
    ALTER TABLE REFDATA.APP_APPLY_TIMING SET SCHEMA CONFIG;
    ALTER TABLE REFDATA.API_LIMIT SET SCHEMA CONFIG;
    ALTER TABLE REFDATA.PROMOTION_METRIC SET SCHEMA CONFIG;
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'quant_app') THEN
        GRANT USAGE ON SCHEMA CONFIG TO quant_app;
    END IF;
END $$;
